// Turun beynidir: kilidi kontrol eder, kulliyati ve iki durum dosyasini okur,
// yapilacak islerin listesini kurar. Faz secimi SABIT BIR AYARDAN DEGIL, her
// reponun kendi kayitli durumundan cikar - bu yuzden ayni workflow hem ilk
// cekimi hem derinlesmeyi hem de sonsuza kadar tazelemeyi yapar.
const fs = require('fs');
const DIZIN = '/data/ds21final/tarihce';
const GIRDI = '/data/ds21final/input/';
const KILIT = DIZIN + '/_kilit.json';
const LIMIT = 1100;
const TAVAN = 40;
const KILIT_DK = 20;

try { fs.mkdirSync(DIZIN, { recursive: true }); } catch (e) {}

// --- kilit: onceki tur hala kosuyorsa bu turu tamamen atla ---
// Eski workflow'da 112 mukerrer cekim tam olarak bunun yoklugundan olusmustu.
if (fs.existsSync(KILIT)) {
  try {
    const k = JSON.parse(fs.readFileSync(KILIT, 'utf8'));
    const yas = (Date.now() - new Date(k.an).getTime()) / 60000;
    if (yas < KILIT_DK) {
      console.log('kilit var (' + yas.toFixed(1) + ' dk) - tur atlandi');
      return [{ json: { atlandi: true, kilit_yasi_dk: Number(yas.toFixed(1)) } }];
    }
  } catch (e) {}
}

// --- kulliyat: diger workflow'larin okudugu AYNI girdi dosyalari ---
const repolar = [];
for (let i = 1; i <= 5; i++) {
  const yol = GIRDI + 'repos_meta' + i + '.csv';
  if (!fs.existsSync(yol)) { continue; }
  const satirlar = fs.readFileSync(yol, 'utf8').split('\n');
  for (let k = 1; k < satirlar.length; k++) {
    const s = satirlar[k].trim();
    if (s) { repolar.push(s.split(',')[0]); }
  }
}

// --- durum: repo basina SON satir kazanir ---
function durumOku(dosya) {
  const d = {};
  const yol = DIZIN + '/' + dosya;
  if (!fs.existsSync(yol)) { return d; }
  for (const s of fs.readFileSync(yol, 'utf8').split('\n')) {
    if (!s.trim()) { continue; }
    try { const r = JSON.parse(s); if (r.full_name) { d[r.full_name] = r; } } catch (e) {}
  }
  return d;
}
const cD = durumOku('commit_durum.jsonl');
const pD = durumOku('push_durum.jsonl');

const BITTI_C = ['ok', 'bos', 'erisilemez', '304'];
const BITTI_P = ['tam', 'api_bitti', 'tavan', 'yok', 'erisilemez', '304'];

const TAZELEME_GUN = 7;

// AUDIT 2026-09-11 | TAZELEME KOVASI EKLENDI.
// Bu dosyanin ust yorumu "ayni workflow ... sonsuza kadar tazelemeyi yapar"
// diyordu ama KOD OYLE YAPMIYORDU: bir repo `ok`/`tam` olduktan sonra hicbir
// kosulda yeniden kuyruga girmiyordu. Yas kontrolu YOKTU. Yani `haftalik.bat`'in
// "n8n zaten cekimi zamanliyor" varsayimi da bosluktaydi - model her hafta
// yeniden skorlanabiliyordu ama skorladigi veri DONMUSTU.
// Kodda karsiligi olmayan bir tasarim niyeti, bir niyettir.
function yasGun(iso) {
  if (!iso) { return 1e9; }
  const t = new Date(iso).getTime();
  return isNaN(t) ? 1e9 : (Date.now() - t) / 86400000;
}

const C1 = [], C2 = [], C3 = [], P1 = [], P2 = [], P3 = [];
const baslangic = new Date().toISOString();

for (const ad of repolar) {
  const cUrl = 'https://api.github.com/repos/' + ad + '/stats/contributors';

  // ---- commit ----
  const c = cD[ad];
  if (!c) {
    C1.push({ full_name: ad, is: 'commit', url: cUrl, etag: '', deneme: 0 });
  } else if (BITTI_C.indexOf(c.durum) < 0 && (c.deneme || 0) < 5) {
    // 'hesaplaniyor' (202) ya da gecici hata: GitHub istatistigi asenkron
    // uretiyor, sonraki turda hazir olur.
    C2.push({ full_name: ad, is: 'commit', url: cUrl, etag: c.etag || '',
              deneme: c.deneme || 0 });
  } else if (c.durum !== 'erisilemez' && yasGun(c.cekim) > TAZELEME_GUN) {
    // TAZELEME. /stats/contributors reponun TUM OMRUNU tek yanitta dondurur,
    // yani bir istek tam tazeleme demek - artimli birlestirme gerekmiyor.
    // ETag tasiniyor: degismemisse GitHub 304 doner ve kota sayacina GIRMEZ.
    // `erisilemez` HARIC: repo GitHub'dan silinmis, haftalik 404 yemek bosuna.
    C3.push({ full_name: ad, is: 'commit', url: cUrl, etag: c.etag || '',
              deneme: 0 });
  }

  // ---- push ----
  const p = pD[ad];
  if (!p) {
    P1.push({ full_name: ad, is: 'push', sayfa: 1, en_erken: 0, olay_top: 0,
              deneme: 0, etag: '',
              url: 'https://api.github.com/repos/' + ad + '/activity?per_page=100' });
  } else if (p.durum === 'derinlesiyor' && p.imlec && (p.sayfa || 1) < TAVAN) {
    // imlec URL'i GitHub'in Link basligindan geldi. ?page= KULLANILMAZ:
    // olculdu, sessizce ayni sayfayi donduruyor.
    P2.push({ full_name: ad, is: 'push', sayfa: (p.sayfa || 1) + 1,
              en_erken: p.en_erken || 0, olay_top: p.olay || 0,
              deneme: 0, etag: '', url: p.imlec });
  } else if (BITTI_P.indexOf(p.durum) < 0 && (p.deneme || 0) < 3) {
    // hata: ayni URL'i yeniden dene
    P2.push({ full_name: ad, is: 'push', sayfa: p.sayfa || 1,
              en_erken: p.en_erken || 0, olay_top: p.olay || 0,
              deneme: p.deneme || 0, etag: '',
              url: p.son_url || ('https://api.github.com/repos/' + ad + '/activity?per_page=100') });
  } else if (p.durum !== 'erisilemez' && yasGun(p.cekim) > TAZELEME_GUN) {
    // TAZELEME. Yeni olaylar akisin BASINDA durur, yani 1. sayfa yeter.
    //
    // 🔑 NUMARA: `en_erken` ILERI TASINIYOR. Durum kurali (asagida :346)
    //    `enErken <= HEDEF_TS ise durum='tam'` diyor; eski deger zaten bu
    //    kosulu sagladigi icin repo 1. sayfadan sonra dogrudan `tam`'a doner
    //    ve TUM SAYFALARI YENIDEN YURUMEZ. en_erken'i 0 verseydik 24.664 repo
    //    bastan T-365'e kadar yeniden cekilirdi.
    // `etag1` ile sartli istek: degismemisse 304.
    // `tavan`daki repolar icin sayfa sayaci da tasiniyor, yoksa 1. sayfadan
    //    sonra `derinlesiyor`a dusup 40 sayfa yeniden yururlerdi (498 repo).
    // ⚠️ BILINEN SINIR: bir repo tazeleme araliginda 100'den cok olay aldiysa
    //    1. sayfa yetmez ve fazlasi kacar. TAZELEME_GUN=7'de bu cok nadir;
    //    olculdu: repolarin %80,6'si 5 HAFTADA hic push almiyor.
    P3.push({ full_name: ad, is: 'push',
              sayfa: (p.durum === 'tavan' ? (p.sayfa || 1) : 1),
              en_erken: p.en_erken || 0, olay_top: p.olay || 0,
              deneme: 0, etag: p.etag1 || '',
              url: 'https://api.github.com/repos/' + ad + '/activity?per_page=100' });
  }
}

// --- GENISLIK ONCE: hic dokunulmamislar donusumlu, sonra derinlesme ---
function harmanla(a, b) {
  const o = [];
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (i < a.length) { o.push(a[i]); }
    if (i < b.length) { o.push(b[i]); }
  }
  return o;
}
const liste = harmanla(C1, P1).concat(harmanla(C2, P2)).concat(harmanla(C3, P3)).slice(0, LIMIT);
for (const x of liste) { x.baslangic = baslangic; }

fs.writeFileSync(DIZIN + '/_baslangic.json', JSON.stringify({
  an: baslangic, kulliyat: repolar.length,
  commit_bekleyen: C1.length, commit_tekrar: C2.length, commit_tazeleme: C3.length,
  push_bekleyen: P1.length, push_derinlesme: P2.length, push_tazeleme: P3.length,
  tazeleme_gun: TAZELEME_GUN,
  bu_kosuda: liste.length
}, null, 2));

if (!liste.length) {
  console.log('yapilacak is yok - her sey guncel (tazeleme esigi ' + TAZELEME_GUN + ' gun)');
  return [{ json: { bitti: true, kulliyat: repolar.length } }];
}

fs.writeFileSync(KILIT, JSON.stringify({ an: baslangic, is: liste.length }));
console.log('kulliyat=' + repolar.length + ' C1=' + C1.length + ' P1=' + P1.length +
            ' C2=' + C2.length + ' P2=' + P2.length +
            ' C3=' + C3.length + ' P3=' + P3.length + ' bu_kosuda=' + liste.length);
return liste.map(function (x) { return { json: x }; });

// Iki ucun TEK yazicisi. batchSize 1 oldugu icin bu yanit hangi repoya ait
// sorusunun cevabi belirsizlik tasimaz: dongunun o anki item'i.
const fs = require('fs');
const DIZIN = '/data/ds21final/tarihce';
const TAVAN = 40;
const HEDEF_TS = Math.floor(new Date('2025-03-11T00:00:00Z').getTime() / 1000);

const girdi = $('Gruplara Bol').first().json;
const j = $input.first().json || {};
const kod = j.statusCode || 0;
const bas = j.headers || {};
const govde = j.body;
const an = new Date().toISOString();
const ad = girdi.full_name;

// ---------------------------------------------------------------- COMMIT
if (girdi.is === 'commit') {
  const etag = bas.etag || bas.ETag || girdi.etag || '';
  let durum = 'hata';
  let hafta = 0;

  if (kod === 304) {
    durum = '304';                       // degismemis - kotadan dusmedi
  } else if (kod === 202) {
    durum = 'hesaplaniyor';              // GitHub uretiyor, sonraki turda tekrar
  } else if (kod === 404 || kod === 451) {
    durum = 'erisilemez';                // repo yok / engelli
  } else if (kod === 200 && Array.isArray(govde) && govde.length) {
    // TIDY SEMA fetch_commit_history.py ile BIREBIR AYNI olmak zorunda:
    // yalnizca c > 0 haftalar sayilir, sifir haftalar YAZILMAZ (ozellik
    // kurulumunda reindex ile geri gelirler).
    const h = {};
    for (const katkici of govde) {
      for (const w of (katkici.weeks || [])) {
        if ((w.c || 0) > 0) {
          if (!h[w.w]) { h[w.w] = [0, 0]; }
          h[w.w][0] += w.c;              // o haftaki commit toplami
          h[w.w][1] += 1;                // o hafta aktif katkici sayisi
        }
      }
    }
    const ws = Object.keys(h).map(Number).sort(function (a, b) { return a - b; });
    hafta = ws.length;
    durum = ws.length ? 'ok' : 'bos';
    if (ws.length) {
      fs.appendFileSync(DIZIN + '/commit_weeks.jsonl', JSON.stringify({
        full_name: ad, cekilme: an, status: 'ok', hafta_sayisi: ws.length,
        haftalar: ws.map(function (w) { return [w, h[w][0], h[w][1]]; })
      }) + '\n', 'utf8');
    }
  } else if (kod === 200) {
    durum = 'bos';                       // 200 + bos dizi = repo gercekten bos
  }

  const tekrar = (durum === 'hesaplaniyor' || durum === 'hata');
  fs.appendFileSync(DIZIN + '/commit_durum.jsonl', JSON.stringify({
    full_name: ad, durum: durum, etag: etag, hafta: hafta,
    deneme: (girdi.deneme || 0) + (tekrar ? 1 : 0), cekim: an
  }) + '\n', 'utf8');

  return [{ json: { full_name: ad, is: 'commit', durum: durum, hafta: hafta,
                    kota: bas['x-ratelimit-remaining'] || null } }];
}

// ---------------------------------------------------------------- PUSH
let durum = 'hata';
let olayS = 0;
let enErken = girdi.en_erken || 0;
let imlec = null;
// ETag yalnizca 1. sayfa icin anlamli: ileride tazeleme o sayfaya bakacak.
const etag1 = (girdi.sayfa === 1) ? (bas.etag || bas.ETag || '') : (girdi.etag || '');

if (kod === 304) {
  durum = '304';
} else if (kod === 404 || kod === 451) {
  durum = 'erisilemez';
} else if (kod === 200 && Array.isArray(govde)) {
  // ---- SIRALAMAYA GUVENME ----
  // Eski workflow "id'ler kesin azalan" varsayip ilk eski id'de break ediyordu.
  // Olculdu: kayitlarin %3,37'sinde id'ler azalan DEGIL, yani o break yeni
  // olaylari sessizce atlayabiliyordu. Burada sayfanin TAMAMI aliniyor ve
  // mukerrerler Python'da olay id'sine gore temizleniyor.
  const yeni = [];
  let mn = 0;
  for (const e of govde) {
    const ts = Math.floor(new Date(e.timestamp).getTime() / 1000);
    if (!mn || ts < mn) { mn = ts; }
    yeni.push([e.id, ts, e.activity_type, e.ref || '',
               (e.actor && e.actor.login) ? e.actor.login : '']);
  }
  olayS = yeni.length;
  if (yeni.length) {
    fs.appendFileSync(DIZIN + '/push_events.jsonl', JSON.stringify({
      full_name: ad, cekilme: an, sayfa: girdi.sayfa, olay: yeni
    }) + '\n', 'utf8');
    if (!enErken || mn < enErken) { enErken = mn; }
  }

  // Sonraki sayfa YALNIZCA Link basligindan. ?page= olculdu: yok sayiliyor.
  const lk = bas.link || bas.Link || '';
  const m = lk.match(/<([^>]+)>;\s*rel="next"/);

  if (!govde.length) {
    durum = 'yok';                       // hic aktivite kaydi yok
  } else if (enErken && enErken <= HEDEF_TS) {
    durum = 'tam';                       // hedef derinlige ULASTI
  } else if (govde.length < 100 || !m) {
    durum = 'api_bitti';                 // GitHub'da daha fazlasi YOK
  } else if (girdi.sayfa >= TAVAN) {
    durum = 'tavan';                     // biz durduk - pa_kesik bayragi
  } else {
    durum = 'derinlesiyor';
    imlec = m[1];
  }
}

fs.appendFileSync(DIZIN + '/push_durum.jsonl', JSON.stringify({
  full_name: ad, durum: durum, imlec: imlec, en_erken: enErken,
  sayfa: girdi.sayfa, etag1: etag1, olay: (girdi.olay_top || 0) + olayS,
  son_url: girdi.url, deneme: (girdi.deneme || 0) + (durum === 'hata' ? 1 : 0),
  cekim: an
}) + '\n', 'utf8');

return [{ json: { full_name: ad, is: 'push', durum: durum, sayfa: girdi.sayfa,
                  olay: olayS, kota: bas['x-ratelimit-remaining'] || null } }];

// HTTP dugumunun hata dali: ag seviyesi arizalar (timeout, socket hang up).
// Basarisiz bir istek de MUTLAKA durum satiri yazmali, yoksa repo "hic
// denenmemis" gorunur ve is listesi hep onu one koyar - eski workflow'da
// 404'ler tam bunu yapiyordu.
const fs = require('fs');
const DIZIN = '/data/ds21final/tarihce';
const girdi = $('Gruplara Bol').first().json;
const j = $input.first().json || {};
const an = new Date().toISOString();
const mesaj = (j.error && j.error.message) ? String(j.error.message).slice(0, 80)
                                           : String(j.statusCode || 'bilinmiyor');

if (girdi.is === 'commit') {
  fs.appendFileSync(DIZIN + '/commit_durum.jsonl', JSON.stringify({
    full_name: girdi.full_name, durum: 'hata', etag: girdi.etag || '', hafta: 0,
    deneme: (girdi.deneme || 0) + 1, hata: mesaj, cekim: an
  }) + '\n', 'utf8');
} else {
  fs.appendFileSync(DIZIN + '/push_durum.jsonl', JSON.stringify({
    full_name: girdi.full_name, durum: 'hata', imlec: null,
    en_erken: girdi.en_erken || 0, sayfa: girdi.sayfa || 1, etag1: girdi.etag || '',
    olay: girdi.olay_top || 0, son_url: girdi.url,
    deneme: (girdi.deneme || 0) + 1, hata: mesaj, cekim: an
  }) + '\n', 'utf8');
}
return [{ json: { full_name: girdi.full_name, is: girdi.is, durum: 'hata' } }];

// Sure siniri asildi. Bu item HTTP'ye HIC gitmez; bir sonraki turda yeniden
// listeye girer. Sayi siniri yerine ZAMAN siniri kullanmanin sebebi: dis
// gecikme degistiginde sabit bir istek sayisi anlamini yitiriyor ve tur bir
// sonraki tetiklemeye tasiyor (eski workflow'da 26,5 dakikalik bir kosu
// tam bunu yapmisti).
return [{ json: { full_name: $json.full_name, is: $json.is, durum: 'sure_doldu' } }];

// Diskten YENIDEN hesaplanir, tur boyunca tasinan sayaclardan degil: kosu
// zaman asimiyla kesilse bile diskteki sayilar dogrudur.
const fs = require('fs');
const DIZIN = '/data/ds21final/tarihce';

function ozet(dosya) {
  const son = {};
  let satir = 0;
  const yol = DIZIN + '/' + dosya;
  if (fs.existsSync(yol)) {
    for (const s of fs.readFileSync(yol, 'utf8').split('\n')) {
      if (!s.trim()) { continue; }
      satir++;
      try { const r = JSON.parse(s); if (r.full_name) { son[r.full_name] = r; } } catch (e) {}
    }
  }
  const sayac = {};
  for (const ad in son) { const d = son[ad].durum; sayac[d] = (sayac[d] || 0) + 1; }
  return { satir: satir, repo: Object.keys(son).length, durumlar: sayac };
}

const bas = JSON.parse(fs.readFileSync(DIZIN + '/_baslangic.json', 'utf8'));
const rapor = {
  an: new Date().toISOString(),
  kulliyat: bas.kulliyat,
  bu_kosuda: bas.bu_kosuda,
  kosu_saniye: Math.round((Date.now() - new Date(bas.an).getTime()) / 1000),
  commit: ozet('commit_durum.jsonl'),
  push: ozet('push_durum.jsonl')
};
fs.writeFileSync(DIZIN + '/_rapor.json', JSON.stringify(rapor, null, 2));
try { fs.unlinkSync(DIZIN + '/_kilit.json'); } catch (e) {}   // kilidi birak
console.log(JSON.stringify(rapor));
return [{ json: rapor }];
